  if not is_object(ref) or ref.kind ~= "item" then
    return nil
  end
  local identity = is_object(ref.identity) and ref.identity or {}
  if identity.scheme == "selected" then
    return read_item_summary_resolve_token("selected:" .. tostring(identity.value))
  elseif identity.scheme == "index" then
    return read_item_summary_resolve_token("index:" .. tostring(identity.value))
  elseif identity.scheme == "guid" then
    return read_item_summary_resolve_token("guid:" .. tostring(identity.value))
  end
  return read_item_summary_resolve_token(ref.ref)
end

local function read_item_summary_require_item_number(item, key)
  local ok, value = call_reaper("GetMediaItemInfo_Value", item, key)
  local number = ok and read_item_summary_finite_number(first_number(value)) or nil
  if number == nil then
    return nil, select(2, read_item_summary_command_failed(
      "REAPER did not return a finite Item property for item summary.",
      { api = "GetMediaItemInfo_Value", key = key }
    ))
  end
  return number
end

local function read_item_summary_require_take_number(take, key)
  local ok, value = call_reaper("GetMediaItemTakeInfo_Value", take, key)
  local number = ok and read_item_summary_finite_number(first_number(value)) or nil
  if number == nil then
    return nil, select(2, read_item_summary_command_failed(
      "REAPER did not return a finite Active Take property for item summary.",
      { api = "GetMediaItemTakeInfo_Value", key = key }
    ))
  end
  return number
end

local function read_item_summary_value(item, include_take_summary)
  local item_ref = read_item_summary_item_ref_string(item)
  if not item_ref then
    return read_item_summary_command_failed(
      "REAPER did not return an authoritative Item identity for item summary.",
      { api = "GetSetMediaItemInfo_String", key = "GUID", fallback_api = "BR_GetMediaItemGUID/CountMediaItems/GetMediaItem" }
    )
  end
  local track = read_item_summary_item_track(item)
  if not track then
    return read_item_summary_command_failed(
      "REAPER did not return the owning Track for item summary.",
      { api = "GetMediaItemTrack", fallback_api = "GetMediaItem_Track" }
    )
  end
  local track_ref = read_item_summary_track_ref_string(track)
  if not track_ref then
    return read_item_summary_command_failed(
      "REAPER did not return an authoritative Track identity for item summary.",
      { api = "GetTrackGUID", fallback_api = "GetMediaTrackInfo_Value/CountTracks/GetTrack" }
    )
  end

  local position_seconds, position_failure = read_item_summary_require_item_number(item, "D_POSITION")
  if position_failure then
    return nil, position_failure
  end
  local length_seconds, length_failure = read_item_summary_require_item_number(item, "D_LENGTH")
  if length_failure then
    return nil, length_failure
  end
  local snap_offset_seconds, snap_failure = read_item_summary_require_item_number(item, "D_SNAPOFFSET")
  if snap_failure then
    return nil, snap_failure
  end
  local fade_in_seconds, fade_in_failure = read_item_summary_require_item_number(item, "D_FADEINLEN")
  if fade_in_failure then
    return nil, fade_in_failure
  end
  local fade_out_seconds, fade_out_failure = read_item_summary_require_item_number(item, "D_FADEOUTLEN")
  if fade_out_failure then
    return nil, fade_out_failure
  end
  local item_volume_linear, item_volume_failure = read_item_summary_require_item_number(item, "D_VOL")
  if item_volume_failure then
    return nil, item_volume_failure
  end
  local volume_db = read_item_summary_linear_to_db(item_volume_linear)
  if volume_db == nil then
    return read_item_summary_command_failed(
      "REAPER returned a non-finite Item D_VOL value for item summary.",
      { api = "GetMediaItemInfo_Value", key = "D_VOL" }
    )
  end

  local summary = {
    item_ref = item_ref,
    track_ref = track_ref,
    position_seconds = position_seconds,
    length_seconds = length_seconds,
    snap_offset_seconds = snap_offset_seconds,
    fade_in_seconds = fade_in_seconds,
    fade_out_seconds = fade_out_seconds,
    volume_db = volume_db,
  }

  if not include_take_summary then
    return summary
  end

  local ok_take_count, take_count_raw = call_reaper("CountTakes", item)
  local take_count = ok_take_count and read_item_summary_finite_number(first_number(take_count_raw)) or nil
  if take_count == nil or take_count < 0 or take_count ~= math.floor(take_count) then
    return read_item_summary_command_failed(
      "REAPER did not return a finite non-negative CountTakes value for item summary.",
      { api = "CountTakes" }
    )
  end
  take_count = math.floor(take_count)
  summary.take_count = take_count

  local ok_take, take = call_reaper("GetActiveTake", item)
  if not ok_take then
    return read_item_summary_command_failed(
      "REAPER rejected GetActiveTake during item summary.",
      { api = "GetActiveTake" }
    )
  end

  if not take then
    if take_count > 0 then
      return read_item_summary_command_failed(
        "REAPER reported Takes but did not return the Active Take for item summary.",
        { api = "GetActiveTake", take_count = take_count }
      )
    end
    summary.active_take_ref = JSON_NULL
    summary.active_take_name = ""
    return summary
  end

  if take_count < 1 then
    return read_item_summary_command_failed(
      "REAPER reported an Active Take while CountTakes was zero.",
      { api = "GetActiveTake", take_count = take_count }
    )
  end

  local take_guid = read_item_summary_take_guid(take)
  if not take_guid then
    return read_item_summary_command_failed(
      "Active Take exists but no authoritative Take GUID was available for item summary.",
      {
        api = "GetSetMediaItemTakeInfo_String",
        key = "GUID",
        fallback_api = "BR_GetMediaItemTakeGUID",
      }
    )
  end

  local ok_name, take_name = call_reaper("GetTakeName", take)
  take_name = ok_name and first_string(take_name) or nil
  if take_name == nil then
    return read_item_summary_command_failed(
      "REAPER did not return the Active Take name for item summary.",
      { api = "GetTakeName" }
    )
  end
  summary.active_take_ref = "take:guid:" .. take_guid
  summary.active_take_name = bounded_string(take_name, 160)

  local take_volume_linear, take_volume_failure = read_item_summary_require_take_number(take, "D_VOL")
  if take_volume_failure then
    return nil, take_volume_failure
  end
  local take_volume_db = read_item_summary_linear_to_db(take_volume_linear)
  if take_volume_db == nil then
    return read_item_summary_command_failed(
      "REAPER returned a non-finite Active Take D_VOL value for item summary.",
      { api = "GetMediaItemTakeInfo_Value", key = "D_VOL" }
    )
  end

  local take_pan, take_pan_failure = read_item_summary_require_take_number(take, "D_PAN")
  if take_pan_failure then
    return nil, take_pan_failure
  end
  local take_pitch_semitones, take_pitch_failure = read_item_summary_require_take_number(take, "D_PITCH")
  if take_pitch_failure then
    return nil, take_pitch_failure
  end
  local playrate, playrate_failure = read_item_summary_require_take_number(take, "D_PLAYRATE")
  if playrate_failure then
    return nil, playrate_failure
  end

  local ok_ppitch, ppitch_raw = call_reaper("GetMediaItemTakeInfo_Value", take, "B_PPITCH")
  local ppitch = ok_ppitch and read_item_summary_finite_number(first_number(ppitch_raw)) or nil
  if ppitch ~= 0 and ppitch ~= 1 then
    return read_item_summary_command_failed(
      "REAPER did not return a native 0/1 B_PPITCH value for item summary.",
      { api = "GetMediaItemTakeInfo_Value", key = "B_PPITCH" }
    )
  end

  summary.take_volume_db = take_volume_db
  summary.take_pan = take_pan
  summary.take_pitch_semitones = take_pitch_semitones
  summary.playrate = playrate
  summary.preserve_pitch = ppitch == 1
  return summary
end

local function read_item_summary(request)
  local item = nil
  if is_json_array(request.refs) then
    for index = 1, #request.refs do
      item = read_item_summary_from_ref_object(request.refs[index])
      if item then
        break
      end
    end
  end
  if not item then
    return read_item_summary_error("ITEM_NOT_FOUND", "Item summary requires a resolvable item ref.", {}, true)
  end
  return read_item_summary_value(item, request.params.include_take_summary == true)
end
return {
  exports = { read_item_summary = read_item_summary },
  shared = {  },
}
end)

-- OpenReaper bridge handler module: reaper/bridge/src/handlers/project/read_file_state.lua
__openreaper_register_handler_module("project/read_file_state.lua", function()
-- Alpha3.2-C3A read-only current project file-state handlers.

local READ_FILE_STATE_NAME_MAX_BYTES = 256
local READ_FILE_STATE_PATH_HARD_MAX_BYTES = 4096
local READ_FILE_STATE_RESPONSE_OVERHEAD_BYTES = 512

local function read_file_state_error(code, message, details, recoverable)
  return nil, {
    code = code,
    message = message,
    recoverable = recoverable ~= false,
    details = details or {},
  }
end

local function read_file_state_api_available(name)
  return reaper and type(reaper[name]) == "function"
end

local function read_file_state_bounded_text(value, max_bytes)
  local text = type(value) == "string" and value or tostring(value or "")
  local limit = math.max(4, math.floor(tonumber(max_bytes) or 4))
  if #text <= limit then
    return text, false
  end
  local cut = limit - 3
  while cut > 0 do
    local next_byte = string.byte(text, cut + 1)
    if next_byte == nil or next_byte < 128 or next_byte >= 192 then
      break
    end
    cut = cut - 1
  end
  return text:sub(1, cut) .. "...", true
end

local function read_file_state_current_project()
  if not read_file_state_api_available("EnumProjects") then
    return read_file_state_error("INTERNAL_ERROR", "REAPER EnumProjects API is required for current project file-state reads.", {
      api = "EnumProjects",
      reason = "api_unavailable",
    })
  end
  local ok, project, project_path = pcall(reaper.EnumProjects, -1, "")
  if not ok then
    return read_file_state_error("INTERNAL_ERROR", "REAPER EnumProjects failed while reading the current project.", {
      api = "EnumProjects",
      reason = "pcall_failed",
    })
  end
  if type(project_path) ~= "string" then
    return read_file_state_error("INTERNAL_ERROR", "REAPER EnumProjects returned an invalid project path.", {
      api = "EnumProjects",
      reason = "invalid_result",
      expected = "string_path",
      actual_type = type(project_path),
    })
  end
  return project or 0, project_path
end

local function read_file_state_project_name(project, project_path)
  local name = nil
  if read_file_state_api_available("GetProjectName") then
    local ok, first, second = pcall(reaper.GetProjectName, project, "")
    if ok then
      name = first_string(first, second)
    end
  end
  if type(name) ~= "string" or name == "" then
    name = project_path:match("([^/\\]+)$") or "current"
  end
  local bounded = read_file_state_bounded_text(name, READ_FILE_STATE_NAME_MAX_BYTES)
  return bounded
end

local function read_current_project_path(request)
  local project, project_path_or_error = read_file_state_current_project()
  if project == nil then
    return nil, project_path_or_error
  end
  local project_path = project_path_or_error
  local budget = safe_budget(request)
  local path_limit = math.min(READ_FILE_STATE_PATH_HARD_MAX_BYTES, math.max(256, budget.max_inline_value_bytes - READ_FILE_STATE_RESPONSE_OVERHEAD_BYTES))
  local bounded_path, path_truncated = read_file_state_bounded_text(project_path, path_limit)
  local has_project_path = project_path ~= ""
  return {
    project_ref = "project:current",
    name = read_file_state_project_name(project, project_path),
    path = bounded_path,
    has_project_path = has_project_path,
    path_state = has_project_path and "saved_project" or "unsaved_project",
    path_truncated = path_truncated,
  }
end

local function read_dirty_state(_request)
  local project, project_path_or_error = read_file_state_current_project()
  if project == nil then
    return nil, project_path_or_error
  end
  if not read_file_state_api_available("IsProjectDirty") then
    return read_file_state_error("INTERNAL_ERROR", "REAPER IsProjectDirty API is required for project dirty-state reads.", {
      api = "IsProjectDirty",
      reason = "api_unavailable",
    })
  end
  local ok, raw_dirty_state = pcall(reaper.IsProjectDirty, project)
  if not ok then
    return read_file_state_error("INTERNAL_ERROR", "REAPER IsProjectDirty failed while reading project dirty state.", {
      api = "IsProjectDirty",
      reason = "pcall_failed",
    })
  end
  if
    type(raw_dirty_state) ~= "number" or
    raw_dirty_state ~= raw_dirty_state or
    raw_dirty_state == math.huge or
    raw_dirty_state == -math.huge or
    raw_dirty_state < 0 or
    raw_dirty_state ~= math.floor(raw_dirty_state)
  then
    return read_file_state_error("INTERNAL_ERROR", "REAPER IsProjectDirty returned an invalid dirty-state value.", {
      api = "IsProjectDirty",
      reason = "invalid_result",
      expected = "non_negative_integer",
      actual_type = type(raw_dirty_state),
      actual_value = bounded_string(raw_dirty_state, 80),
    })
  end
  local dirty = raw_dirty_state > 0
  return {
    project_ref = "project:current",
    dirty = dirty,
    dirty_state = dirty and "dirty" or "clean",
    raw_dirty_state = raw_dirty_state,
  }
end
return {
  exports = { read_current_project_path = read_current_project_path, read_dirty_state = read_dirty_state },
  shared = {  },
}
end)

-- OpenReaper bridge handler module: reaper/bridge/src/handlers/project/save_project_file.lua
__openreaper_register_handler_module("project/save_project_file.lua", function()
-- Alpha3.2-C3B+C3C direct project-file save handlers.

local PROJECT_FILE_SAVE_PATH_MAX_BYTES = 2048
local PROJECT_FILE_SAVE_AS_OPTIONS = 8
local PROJECT_FILE_SAVE_SUCCESS_ENVELOPE_FIXED_MAX_BYTES = 16384
local PROJECT_FILE_SAVE_JSON_ESCAPE_FACTOR = 6
local PROJECT_FILE_SAVE_JSON_FIELD_OVERHEAD_BYTES = 96

local function project_file_save_error(code, message, details, recoverable)
  return nil, {
    code = code,
    message = message,
    recoverable = recoverable ~= false,
    details = details or {},
  }
end

local function project_file_save_api_available(name)
  if not reaper or type(reaper.APIExists) ~= "function" then
    return false, "api_exists_unavailable"
  end
  local ok_exists, exists = pcall(reaper.APIExists, name)
  if not ok_exists then
    return false, "api_exists_pcall_failed"
  end
  if exists ~= true then
    return false, "api_unavailable"
  end
  if type(reaper[name]) ~= "function" then
    return false, "binding_unavailable"
  end
  return true
end

local function project_file_save_require_api(name)
  local available, reason = project_file_save_api_available(name)
  if available then
    return true
  end
  return project_file_save_error("INTERNAL_ERROR", "Required direct REAPER project-file API is unavailable.", {
    api = name,
    reason = reason,
  }, false)
end

local function project_file_save_current_project_state()
  local enum_ok, enum_error = project_file_save_require_api("EnumProjects")
  if not enum_ok then
    return nil, enum_error
  end
  local dirty_ok, dirty_error = project_file_save_require_api("IsProjectDirty")
  if not dirty_ok then
    return nil, dirty_error
  end
  local ok_project, project, project_path = pcall(reaper.EnumProjects, -1, "")
  if not ok_project then
    return project_file_save_error("INTERNAL_ERROR", "REAPER EnumProjects failed while reading current project file state.", {
      api = "EnumProjects",
      reason = "pcall_failed",
    }, false)
  end
  if type(project_path) ~= "string" then
    return project_file_save_error("INTERNAL_ERROR", "REAPER EnumProjects returned an invalid current project path.", {
      api = "EnumProjects",
      reason = "invalid_result",
      actual_type = type(project_path),
    }, false)
  end
  local ok_dirty, raw_dirty_state = pcall(reaper.IsProjectDirty, project)
  if not ok_dirty then
    return project_file_save_error("INTERNAL_ERROR", "REAPER IsProjectDirty failed while reading current project dirty state.", {
      api = "IsProjectDirty",
      reason = "pcall_failed",
    }, false)
  end
  if type(raw_dirty_state) ~= "number"
    or raw_dirty_state ~= raw_dirty_state
    or raw_dirty_state == math.huge
    or raw_dirty_state == -math.huge
    or raw_dirty_state < 0
    or raw_dirty_state ~= math.floor(raw_dirty_state) then
    return project_file_save_error("INTERNAL_ERROR", "REAPER IsProjectDirty returned an invalid dirty-state value.", {
      api = "IsProjectDirty",
      reason = "invalid_result",
      actual_type = type(raw_dirty_state),
      actual_value = bounded_string(raw_dirty_state, 80),
    }, false)
  end
  return {
    project = project or 0,
    path = project_path,
    dirty = raw_dirty_state > 0,
    raw_dirty_state = raw_dirty_state,
  }
end

local function project_file_save_success_budget(request, paths)
  local budget = safe_budget(request)
  local max_inline = math.min(PROJECT_FILE_SAVE_PATH_MAX_BYTES, math.floor(tonumber(budget.max_inline_value_bytes) or 0))
  local required_response_bytes = PROJECT_FILE_SAVE_SUCCESS_ENVELOPE_FIXED_MAX_BYTES
  for index = 1, #paths do
    local project_path = paths[index]
    if type(project_path) ~= "string" or max_inline < 1 or #project_path > max_inline then
      return project_file_save_error("RESPONSE_TOO_LARGE", "Exact project path exceeds the request inline-value budget; save was not attempted.", {
        blocker = "exact_path_exceeds_inline_budget",
        path_index = index,
        path_bytes = type(project_path) == "string" and #project_path or -1,
        max_inline_value_bytes = max_inline,
      })
    end
    required_response_bytes = required_response_bytes
      + (#project_path * PROJECT_FILE_SAVE_JSON_ESCAPE_FACTOR)
      + PROJECT_FILE_SAVE_JSON_FIELD_OVERHEAD_BYTES
  end
  if budget.max_response_bytes < required_response_bytes then
    return project_file_save_error("RESPONSE_TOO_LARGE", "Conservative complete success-envelope budget proof failed; save was not attempted.", {
      blocker = "success_envelope_budget_insufficient",
      required_response_bytes = required_response_bytes,
      max_response_bytes = budget.max_response_bytes,
      fixed_max_overhead_bytes = PROJECT_FILE_SAVE_SUCCESS_ENVELOPE_FIXED_MAX_BYTES,
      json_escape_factor = PROJECT_FILE_SAVE_JSON_ESCAPE_FACTOR,
      path_field_count = #paths,
    })
  end
  return true
end

local function project_file_save_project_ref()
  return {
    kind = "project",
    ref = "project:current",
    identity = {
      scheme = "current",
      value = "current",
    },
  }
end

local function project_file_save_refs()
  return json_array({ project_file_save_project_ref() })
end

local function project_file_save_summary(request, values)
  values.capability = request.pack.capability
  values.pack = "project"
  values.risk = "write"
  values.readback_status = "passed"
  values.undo_evidence = "required"
  values.artifacts_allowed = false
  values.truncated = false
  return values
end

local function project_file_save_call_void_api(api_name, ...)
  local api_ok, api_error = project_file_save_require_api(api_name)
  if not api_ok then
    return nil, api_error
  end
  local call_results = { pcall(reaper[api_name], ...) }
  if call_results[1] ~= true then
    return project_file_save_error("COMMAND_FAILED", "Direct REAPER project-file save API call failed.", {
      api = api_name,
      reason = "pcall_failed",
    }, false)
  end
  local returned = call_results[2]
  if returned ~= nil and returned ~= true then
    return project_file_save_error("COMMAND_FAILED", "Direct REAPER project-file save API returned a failure value.", {
      api = api_name,
      reason = "failure_return",
      returned_type = type(returned),
      returned_value = bounded_string(returned, 80),
    }, false)
  end
  return true
end

local function save_current_project(request)
  if not is_json_array(request.refs) or #request.refs ~= 0 then
    return project_file_save_error("REF_INVALID", "save_current_project accepts only the canonical current project and no caller-supplied refs.", {
      expected = "empty_refs_for_project_current",
    })
  end
  local before, before_error = project_file_save_current_project_state()
  if not before then
    return nil, before_error
  end
  if before.path == "" then
    return project_file_save_error("COMMAND_FAILED", "Current project is unsaved; save_current_project will not open Save As UI.", {
      blocker = "unsaved_project",
      project_ref = "project:current",
      recovery = "Use template.project.save_project_as with one validated absolute .RPP target.",
    })
  end
  local success_budget_fits, success_budget_error = project_file_save_success_budget(request, { before.path, before.path })
  if not success_budget_fits then
    return nil, success_budget_error
  end
  local saved, save_error = project_file_save_call_void_api("Main_SaveProject", before.project, false)
  if not saved then
    return nil, save_error
  end
  local after, after_error = project_file_save_current_project_state()
  if not after then
    return nil, after_error
  end
  if after.path ~= before.path then
    return project_file_save_error("VERIFY_FAILED", "save_current_project changed the exact project path unexpectedly.", {
      blocker = "project_path_mismatch",
      before_path = bounded_string(before.path, PROJECT_FILE_SAVE_PATH_MAX_BYTES),
      after_path = bounded_string(after.path, PROJECT_FILE_SAVE_PATH_MAX_BYTES),
    }, false)
  end
  if after.dirty or after.raw_dirty_state ~= 0 then
    return project_file_save_error("VERIFY_FAILED", "save_current_project did not read back a clean raw-zero dirty state.", {
      blocker = "project_dirty_after_save",
      after_dirty = after.dirty,
      after_raw_dirty_state = after.raw_dirty_state,
    }, false)
  end
  return project_file_save_summary(request, {
    project_ref = "project:current",
    before_path = before.path,
    after_path = after.path,
    before_dirty = before.dirty,
    before_raw_dirty_state = before.raw_dirty_state,
    after_dirty = after.dirty,
    after_raw_dirty_state = after.raw_dirty_state,
    path_unchanged = true,
    summary = "Saved the already-named current project; exact path is unchanged and dirty state is clean/raw 0.",
  }), nil, nil, nil, project_file_save_refs()
end

local function project_file_save_as_structural_target(request)
  if not is_object(request.params) or not is_string(request.params.target_path) then
    return project_file_save_error("PARAMS_INVALID", "save_project_as requires the server-validated target_path string.", {
      blocker = "validated_target_missing",
    })
  end
  if request.params.overwrite ~= true then
    return project_file_save_error("PARAMS_INVALID", "save_project_as requires explicit overwrite=true authorization for the preflight-to-REAPER dispatch race.", {
      blocker = "overwrite_true_required_for_dispatch",
      atomic_overwrite_false = "held_future",
    })
  end
  local target = request.params.target_path
  if target == "" or #target > PROJECT_FILE_SAVE_PATH_MAX_BYTES or target:find("[%c%z]") then
    return project_file_save_error("PARAMS_INVALID", "save_project_as target failed bounded structural validation.", {
      blocker = "target_structure_invalid",
    })
  end
  local posix_absolute = target:sub(1, 1) == "/"
  local windows_absolute = target:match("^%a:[/\\]") ~= nil or target:match("^[/\\][/\\]") ~= nil
  if not posix_absolute and not windows_absolute then
    return project_file_save_error("PARAMS_INVALID", "save_project_as target must remain absolute at the bridge boundary.", {
      blocker = "target_not_absolute",
    })
  end
  if target:match("^[%a][%w+.-]*://") or target:match("^[%a][%w+.-]*:[^/\\]") then
    return project_file_save_error("PARAMS_INVALID", "save_project_as rejects URI and URL targets at the bridge boundary.", {
      blocker = "target_uri_rejected",
    })
  end
  if target:match("[/\\]%.%.[/\\]") or target:match("[/\\]%.[/\\]") then
    return project_file_save_error("PARAMS_INVALID", "save_project_as rejects dot-segment target paths at the bridge boundary.", {
      blocker = "target_dot_segment_rejected",
    })
  end
  local basename = target:match("([^/\\]+)$")
  if not basename or basename == "" or not basename:lower():match("%.rpp$") then
    return project_file_save_error("PARAMS_INVALID", "save_project_as accepts only a non-empty .RPP target basename.", {
      blocker = "target_extension_invalid",
    })
  end
  return target, request.params.overwrite
end

local function save_project_as(request)
  if not is_json_array(request.refs) or #request.refs ~= 0 then
    return project_file_save_error("REF_INVALID", "save_project_as accepts only the canonical current project and no caller-supplied refs.", {
      expected = "empty_refs_for_project_current",
    })
  end
  local target, overwrite_or_error = project_file_save_as_structural_target(request)
  if not target then
    return nil, overwrite_or_error
  end
  local overwrite = overwrite_or_error
  local before, before_error = project_file_save_current_project_state()
  if not before then
    return nil, before_error
  end
  local success_budget_fits, success_budget_error = project_file_save_success_budget(request, { before.path, target, target })
  if not success_budget_fits then
    return nil, success_budget_error
  end
  local saved, save_error = project_file_save_call_void_api("Main_SaveProjectEx", before.project, target, PROJECT_FILE_SAVE_AS_OPTIONS)
  if not saved then
    return nil, save_error
  end
  local after, after_error = project_file_save_current_project_state()
  if not after then
    return nil, after_error
  end
  if after.path ~= target then
    return project_file_save_error("VERIFY_FAILED", "save_project_as project path readback did not exactly match the validated target.", {
      blocker = "project_path_target_mismatch",
      before_path = bounded_string(before.path, PROJECT_FILE_SAVE_PATH_MAX_BYTES),
      expected_path = bounded_string(target, PROJECT_FILE_SAVE_PATH_MAX_BYTES),
      after_path = bounded_string(after.path, PROJECT_FILE_SAVE_PATH_MAX_BYTES),
      overwrite = overwrite,
    }, false)
  end
  if after.dirty or after.raw_dirty_state ~= 0 then
    return project_file_save_error("VERIFY_FAILED", "save_project_as did not read back a clean raw-zero dirty state.", {
      blocker = "project_dirty_after_save_as",
      expected_path = bounded_string(target, PROJECT_FILE_SAVE_PATH_MAX_BYTES),
      after_dirty = after.dirty,
      after_raw_dirty_state = after.raw_dirty_state,
      overwrite = overwrite,
    }, false)
  end
  return project_file_save_summary(request, {
    project_ref = "project:current",
    before_path = before.path,
    after_path = after.path,
    before_dirty = before.dirty,
    before_raw_dirty_state = before.raw_dirty_state,
    after_dirty = after.dirty,
    after_raw_dirty_state = after.raw_dirty_state,
    target_path = target,
    overwrite = overwrite,
    path_matches_target = true,
    summary = "Saved the current project as the exact validated .RPP target under explicit overwrite=true race authorization; current-project identity remains canonical and dirty state is clean/raw 0.",
  }), nil, nil, nil, project_file_save_refs()
end
return {
  exports = { save_current_project = save_current_project, save_project_as = save_project_as },
  shared = {  },
}
end)

-- OpenReaper bridge handler module: reaper/bridge/src/handlers/project/tempo_write.lua
__openreaper_register_handler_module("project/tempo_write.lua", function()
-- Extracted D6 handler: project tempo/BPM writes.

local function d6_tempo_error(code, message, details, recoverable)
  return nil, {
    code = code,
    message = message,
    recoverable = recoverable ~= false,
    details = details or {},
  }
end

local function d6_tempo_current_project()
  local ok, project = call_reaper("EnumProjects", -1, "")
  if ok then
    return project or 0
  end
  return 0
end

local function d6_tempo_project_ref()
  return {
    kind = "project",
    ref = "project:current",
    identity = {
      scheme = "current",
      value = "current",
    },
  }
end

local function d6_tempo_bounded_bpm(value)
  if type(value) ~= "number" or value ~= value or value == math.huge or value == -math.huge then
    return nil
  end
  if value < 20 or value > 400 then
    return nil
  end
  return value
end

local function d6_tempo_time_sig_num(value)
  local number = math.floor(tonumber(value) or 4)
  if number < 1 then
    return 4
  end
  if number > 32 then
    return 32
  end
  return number
end

local function d6_tempo_time_sig_denom(value)
  local number = math.floor(tonumber(value) or 4)
  if number == 1 or number == 2 or number == 4 or number == 8 or number == 16 or number == 32 then
    return number
  end
  return 4
end

local function d6_tempo_effective_at(project, position_seconds)
  local ok, timesig_num, timesig_denom, bpm = call_reaper("TimeMap_GetTimeSigAtTime", project, position_seconds)
  return {
    bpm = ok and first_number(bpm) or 0,
    time_sig_num = ok and math.floor(first_number(timesig_num) or 0) or 0,
    time_sig_denom = ok and math.floor(first_number(timesig_denom) or 0) or 0,
  }
end

local function d6_tempo_current_bpm(project)
  local ok, bpm = call_reaper("Master_GetTempo")
  if ok and type(bpm) == "number" then
    return bpm
  end
  return d6_tempo_effective_at(project, 0).bpm
end

local function d6_tempo_summary(request, fields)
  fields = fields or {}
  fields.capability = request.pack.capability
  fields.pack = request.pack.id
  fields.risk = request.pack.risk
  fields.readback_status = "passed"
  fields.undo_evidence = "required"
  fields.artifacts_allowed = false
  fields.project_ref = "project:current"
  fields.truncated = false
  return fields
end

local function d6_tempo_refs()
  return json_array({ d6_tempo_project_ref() })
end

local function d6_tempo_set_base(request)
  local project = d6_tempo_current_project()
  local bpm = d6_tempo_bounded_bpm(request.params.bpm)
  if not bpm then
    return d6_tempo_error("BPM_INVALID", "Project tempo writes require bpm between 20 and 400.", {
      bpm = request.params.bpm,
    })
  end
  local ok = call_reaper("SetCurrentBPM", project, bpm, false)
  if not ok then
    return d6_tempo_error("COMMAND_FAILED", "REAPER rejected SetCurrentBPM.", {
      bpm = bpm,
    }, false)
  end
  call_reaper("UpdateTimeline")
  local readback_bpm = d6_tempo_current_bpm(project)
  local updated = math.abs(readback_bpm - bpm) < 0.01
  if not updated then
    return d6_tempo_error("READBACK_MISMATCH", "Project tempo write did not read back the requested BPM.", {
      requested_bpm = bpm,
      readback_bpm = readback_bpm,
    }, false)
  end
  return d6_tempo_summary(request, {
    bpm = readback_bpm,
    requested_bpm = bpm,
    updated = updated,
    preserve_tempo_markers = request.params.preserve_tempo_markers == true,
  }), nil, json_array({}), json_array({}), d6_tempo_refs()
end

local function d6_tempo_marker_count(project)
  local ok_count, count = call_reaper("CountTempoTimeSigMarkers", project)
  return ok_count and math.max(0, math.floor(first_number(count) or 0)) or 0
end

local function d6_tempo_marker_index_at(project, position_seconds)
  local total = d6_tempo_marker_count(project)
  for index = 0, total - 1 do
    local ok_marker, retval, timepos = call_reaper("GetTempoTimeSigMarker", project, index)
    if ok_marker and retval and math.abs((first_number(timepos) or 0) - position_seconds) < 0.000001 then
      return index
    end
  end
  return -1
end

local function d6_tempo_marker_readback_by_index(project, marker_index)
  if marker_index < 0 then
    return nil
  end
  local ok_marker, retval, timepos, measurepos, beatpos, bpm, timesig_num, timesig_denom, lineartempo =
    call_reaper("GetTempoTimeSigMarker", project, marker_index)
  if not ok_marker or not retval then
    return nil
  end
  return {
    marker_index = marker_index,
    position_seconds = first_number(timepos) or position_seconds,
    bpm = first_number(bpm) or 0,
    time_sig_num = math.floor(first_number(timesig_num) or 0),
    time_sig_denom = math.floor(first_number(timesig_denom) or 0),
    linear_tempo = lineartempo == true,
  }
end

local function d6_tempo_marker_readback(project, position_seconds, marker_index)
  local readback_index = marker_index
  if readback_index == nil or readback_index < 0 then
    readback_index = d6_tempo_marker_index_at(project, position_seconds)
  end
  return d6_tempo_marker_readback_by_index(project, readback_index)
end

local function d6_tempo_marker_readback_by_values(project, position_seconds, bpm, numerator, denominator)
  local total = d6_tempo_marker_count(project)
  local best = nil
  local best_distance = nil
  for index = 0, total - 1 do
    local marker = d6_tempo_marker_readback_by_index(project, index)
    if marker
      and math.abs(marker.bpm - bpm) < 0.01
      and marker.time_sig_num == numerator
      and marker.time_sig_denom == denominator then
      local distance = math.abs((marker.position_seconds or position_seconds) - position_seconds)
      if best == nil or distance < best_distance then
        best = marker
        best_distance = distance
      end
    end
  end
  return best
end

local function d6_tempo_set_marker(request)
  local project = d6_tempo_current_project()
  local bpm = d6_tempo_bounded_bpm(request.params.bpm)
  if not bpm then
    return d6_tempo_error("BPM_INVALID", "Tempo marker writes require bpm between 20 and 400.", {
      bpm = request.params.bpm,
    })
  end
  local position_seconds = tonumber(request.params.position_seconds) or 0
  if position_seconds < 0 then
    return d6_tempo_error("POSITION_INVALID", "Tempo marker position_seconds must be non-negative.", {
      position_seconds = request.params.position_seconds,
    })
  end
  local numerator = d6_tempo_time_sig_num(request.params.time_signature_numerator)
  local denominator = d6_tempo_time_sig_denom(request.params.time_signature_denominator)
  local linear_tempo = request.params.linear_tempo == true
  local marker_index = d6_tempo_marker_index_at(project, position_seconds)
  local count_before = d6_tempo_marker_count(project)
  local ok, retval
  if marker_index < 0 then
    ok, retval = call_reaper(
      "AddTempoTimeSigMarker",
      project,
      position_seconds,
      bpm,
      numerator,
      denominator,
      linear_tempo
    )
  else
    ok, retval = call_reaper(
      "SetTempoTimeSigMarker",
      project,
      marker_index,
      position_seconds,
      -1,
      -1,
      bpm,
      numerator,
      denominator,
      linear_tempo
    )
  end
  if not ok or retval == false then
    return d6_tempo_error("COMMAND_FAILED", "REAPER rejected tempo marker update.", {
      position_seconds = position_seconds,
      bpm = bpm,
      marker_index = marker_index,
    }, false)
  end
  call_reaper("UpdateTimeline")
  if marker_index < 0 then
    local count_after = d6_tempo_marker_count(project)
    if count_after > count_before then
      marker_index = count_after - 1
    end
  end
  local readback = d6_tempo_marker_readback(project, position_seconds, marker_index)
  if not readback then
    readback = d6_tempo_marker_readback_by_values(project, position_seconds, bpm, numerator, denominator)
  end
  local updated = readback and math.abs(readback.bpm - bpm) < 0.01
  if not updated then
    return d6_tempo_error("READBACK_MISMATCH", "Tempo marker write did not read back the requested BPM.", {
      position_seconds = position_seconds,
      marker_index = marker_index,
      requested_bpm = bpm,
      readback_bpm = readback and readback.bpm or JSON_NULL,
      time_sig_num = readback and readback.time_sig_num or JSON_NULL,
      time_sig_denom = readback and readback.time_sig_denom or JSON_NULL,
    }, false)
  end
  return d6_tempo_summary(request, {
    requested_position_seconds = position_seconds,
    position_seconds = readback.position_seconds,
    bpm = readback.bpm,
    requested_bpm = bpm,
    time_sig_num = readback.time_sig_num,
    time_sig_denom = readback.time_sig_denom,
    marker_index = readback.marker_index,
    linear_tempo = readback.linear_tempo,
    updated = updated,
  }), nil, json_array({}), json_array({}), d6_tempo_refs()
end

local function d6_project_set_tempo(request)
  return d6_tempo_set_base(request)
end

local function d6_project_set_bpm(request)
  return d6_tempo_set_base(request)
end

local function d6_project_set_tempo_marker(request)
  return d6_tempo_set_marker(request)
end
return {
  exports = { d6_project_set_tempo = d6_project_set_tempo, d6_project_set_bpm = d6_project_set_bpm, d6_project_set_tempo_marker = d6_project_set_tempo_marker },
  shared = {  },
}
end)

-- OpenReaper bridge handler module: reaper/bridge/src/handlers/project/d20_project_grid_snap.lua
__openreaper_register_handler_module("project/d20_project_grid_snap.lua", function()
-- Extracted D20 handler: project grid writes.

local function d20_project_grid_error(code, message, details, recoverable)
  return nil, {
    code = code,
    message = message,
    recoverable = recoverable ~= false,
    details = details or {},
  }
end

local function d20_project_grid_current_project()
  local ok, project = call_reaper("EnumProjects", -1, "")
  if ok then
    return project or 0
  end
  return 0
end

local function d20_project_grid_refs()
  return json_array({
    {
      kind = "project",
      ref = "project:current",
      identity = {
        scheme = "current",
        value = "current",
      },
    },
  })
end

local function d20_project_grid_summary(request, fields)
  fields = fields or {}
  fields.capability = request.pack.capability
  fields.pack = request.pack.id
  fields.risk = request.pack.risk
  fields.readback_status = "passed"
  fields.undo_evidence = "required"
  fields.artifacts_allowed = false
  fields.project_ref = "project:current"
  fields.truncated = false
  return fields
end

local function d20_project_grid_division(value)
  if type(value) == "number" and value == value and value > 0 and value <= 64 then
    return value, tostring(value)
  end
  if type(value) ~= "string" then
    return nil, nil
  end
  local numerator, denominator = value:match("^%s*(%d+)%s*/%s*(%d+)%s*$")
  if numerator and denominator then
    local num = tonumber(numerator)
    local den = tonumber(denominator)
    if num and den and num > 0 and den > 0 then
      local division = (num / den) * 4
      if division > 0 and division <= 64 then
        return division, tostring(num) .. "/" .. tostring(den)
      end
    end
  end
  local numeric = tonumber(value)
  if numeric and numeric > 0 and numeric <= 64 then
    return numeric, tostring(numeric)
  end
  return nil, nil
end

local function d20_project_grid_read(project)
  local ok, retval, division, swingmode, swingamt = call_reaper("GetSetProjectGrid", project, false, 0, 0, 0)
  if ok and type(division) == "number" then
    return {
      division = division,
      swingmode = type(swingmode) == "number" and swingmode or 0,
      swing = type(swingamt) == "number" and swingamt or 0,
    }
  end
  return nil
end

local function d20_project_snap_read(project)
  local ok, enabled = call_reaper("GetToggleCommandStateEx", 0, 1157)
  if ok and type(enabled) == "number" then
    return enabled ~= 0
  end
  local ok_info, value = call_reaper("GetSetProjectInfo", project, "PROJECT_GRID_USE", 0, false)
  if ok_info and type(value) == "number" then
    return value ~= 0
  end
  return nil
end

local function d20_project_set_grid(request)
  local project = d20_project_grid_current_project()
  local division, division_label = d20_project_grid_division(request.params.division)
  if not division then
    return d20_project_grid_error("GRID_DIVISION_INVALID", "Project grid division must be a positive numeric value or fraction string.", {
      division = request.params.division,
    })
  end
  local swing = tonumber(request.params.swing) or 0
  if swing < 0 then
    swing = 0
  elseif swing > 1 then
    swing = 1
  end
  local swingmode = swing > 0 and 1 or 0
  local ok = call_reaper("GetSetProjectGrid", project, true, division, swingmode, swing)
  if not ok then
    return d20_project_grid_error("COMMAND_FAILED", "REAPER rejected project grid update.", {
      division = division_label,
      division_qn = division,
      swing = swing,
    }, false)
  end
  call_reaper("UpdateTimeline")
  local readback = d20_project_grid_read(project)
  local updated = readback and math.abs(readback.division - division) < 0.000001
  if not updated then
    return d20_project_grid_error("READBACK_MISMATCH", "Project grid division did not read back the requested value.", {
      requested_division = division_label,
      requested_division_qn = division,
      requested_swing = swing,
      readback_division_qn = readback and readback.division or JSON_NULL,
      readback_swingmode = readback and readback.swingmode or JSON_NULL,
      readback_swing = readback and readback.swing or JSON_NULL,
    }, false)
  end
  return d20_project_grid_summary(request, {
    division = division_label,
    division_qn = readback.division,
    swingmode = readback.swingmode,
    swing = readback.swing,
    updated = true,
  }), nil, json_array({}), json_array({}), d20_project_grid_refs()
end

local function d20_project_set_snap(request)
  local project = d20_project_grid_current_project()
  local enabled = request.params.enabled == true
  local ok = call_reaper("GetSetProjectInfo", project, "PROJECT_GRID_USE", enabled and 1 or 0, true)
  if not ok then
    return d20_project_grid_error("COMMAND_FAILED", "REAPER rejected project snap update.", {
      enabled = enabled,
    }, false)
  end
  call_reaper("UpdateTimeline")
  local readback = d20_project_snap_read(project)
  if readback == nil then
    return d20_project_grid_error("READBACK_UNAVAILABLE", "Project snap state could not be read back.", {
      enabled = enabled,
    }, false)
  end
  if readback ~= enabled then
    return d20_project_grid_error("READBACK_MISMATCH", "Project snap state did not read back the requested value.", {
      requested_enabled = enabled,
      readback_enabled = readback,
    }, false)
  end
  return d20_project_grid_summary(request, {
    enabled = readback,
    updated = true,
  }), nil, json_array({}), json_array({}), d20_project_grid_refs()
end
return {
  exports = { d20_project_set_grid = d20_project_set_grid, d20_project_set_snap = d20_project_set_snap },
  shared = {  },
}
end)

-- OpenReaper bridge handler module: reaper/bridge/src/handlers/render/d21_render_read_route.lua
__openreaper_register_handler_module("render/d21_render_read_route.lua", function()
-- Extracted D21 handler: render read-only controls.

local function d21_render_error(code, message, details, recoverable)
  return nil, {
    code = code,
    message = message,
    recoverable = recoverable ~= false,
    details = details or {},
  }
end

local function bounded_limit(request, requested, default_limit, hard_limit)
  local budget = safe_budget(request)
  local limit = default_limit or budget.max_items
  if is_non_negative_integer(requested) and requested > 0 then
    limit = requested
  end
  limit = math.min(limit, budget.max_items, hard_limit or budget.max_items)
  if limit < 1 then
    return 1
  end
  return limit
end

local function d21_render_current_project()
  local ok, project = call_reaper("EnumProjects", -1, "")
  if ok then
    return project or 0
  end
  return 0
end

local function d21_render_string(project, key, max_length)
  local ok, _, value = call_reaper("GetSetProjectInfo_String", project, key, "", false)
  if ok and type(value) == "string" then
    return bounded_string(value, max_length or 240)
  end
  return ""
end

local function d21_render_number(project, key, fallback)
  local ok, value = call_reaper("GetSetProjectInfo", project, key, 0, false)
  if ok and type(value) == "number" then
    return value
  end
  return fallback or 0
end

local function d21_render_summary(request, fields)
  fields = fields or {}
  fields.capability = request.pack.capability
  fields.pack = request.pack.id
  fields.risk = request.pack.risk
  fields.readback_status = "passed"
  fields.artifacts_allowed = false
  fields.truncated = false
  return fields
end

local function d21_render_region_ref(region_index)
  return "region:index:" .. tostring(region_index or 0)
end

local function d21_render_track_guid(track)
  local ok, guid = call_reaper("GetTrackGUID", track)
  return ok and first_string(guid) or nil
end

local function d21_render_track_index(track)
  local ok_number, number = call_reaper("GetMediaTrackInfo_Value", track, "IP_TRACKNUMBER")
  if ok_number and type(number) == "number" and number > 0 then
    return math.floor(number - 1)
  end
  return 0
end

local function d21_render_track_ref(track)
  local guid = d21_render_track_guid(track)
  if guid then
    return "track:guid:" .. guid
  end
  return "track:index:" .. tostring(d21_render_track_index(track))
end

local function d21_render_ref_object(kind, ref, scheme, value, summary)
  return {
    kind = kind,
    ref = ref,
    identity = {
      scheme = scheme,
      value = value,
    },
    summary = summary,
  }
end

local function d21_render_region_token_from_request(request)
  for index = 1, #request.refs do
    local ref = request.refs[index]
    if ref.kind == "region" then
      local raw = ref.ref or ""
      local by_index = raw:match("^region:index:(%-?%d+)$")
      if by_index then
        return { scheme = "index", value = tonumber(by_index), ref = raw }
      end
      local by_name = raw:match("^region:name:(.+)$")
      if by_name then
        return { scheme = "name", value = by_name, ref = raw }
      end
    end
  end
  return nil
end

local function d21_render_regions(project, limit)
  local regions = json_array({})
  local ok_count, marker_count, region_count = call_reaper("CountProjectMarkers", project)
  local total = ok_count and math.max(0, math.floor((first_number(marker_count) or 0) + (first_number(region_count) or 0))) or 0
  local max_regions = math.min(limit or 100, 256)
  for index = 0, total - 1 do
    local ok, retval, is_region, start_pos, end_pos, name, region_index = call_reaper("EnumProjectMarkers3", project, index)
    if ok and retval and is_region == true then
      regions[#regions + 1] = {
        index = math.floor(first_number(region_index) or (#regions + 1)),
        name = bounded_string(first_string(name) or "", 160),
        start_seconds = first_number(start_pos) or 0,
        end_seconds = first_number(end_pos) or 0,
      }
      if #regions >= max_regions then
        break
      end
    end
  end
  return regions
end

local function d21_render_resolve_region(request)
  local project = d21_render_current_project()
  local token = d21_render_region_token_from_request(request)
  if not token then
    return nil, "REGION_REF_REQUIRED", "Render region read requires a region ref."
  end
  local matches = json_array({})
  local regions = d21_render_regions(project, 256)
  for index = 1, #regions do
    local region = regions[index]
    if token.scheme == "index" and region.index == token.value then
      matches[#matches + 1] = region
    elseif token.scheme == "name" and region.name == token.value then
      matches[#matches + 1] = region
    end
  end
  if #matches == 1 then
    return matches[1], nil, nil
  end
  if #matches > 1 then
    return nil, "REGION_AMBIGUOUS", "Render region ref matched multiple regions."
  end
  return nil, "REGION_NOT_FOUND", "Render region ref could not be resolved."
end

local function d21_render_bounds_from_kind(request)
  local project = d21_render_current_project()
  local kind = request.params.bounds_kind or "current_settings"
  if kind == "custom" then
    local start_seconds = tonumber(request.params.start_position_seconds)
    local end_seconds = tonumber(request.params.end_position_seconds)
    if not start_seconds or not end_seconds or start_seconds < 0 or end_seconds < start_seconds then
      return nil, d21_render_error("BOUNDS_INVALID", "Custom render bounds require non-negative start/end with end >= start.", {
        start_position_seconds = request.params.start_position_seconds,
        end_position_seconds = request.params.end_position_seconds,
      })
    end
    return {
      resolved_kind = "custom",
      start_position_seconds = start_seconds,
      end_position_seconds = end_seconds,
      duration_seconds = end_seconds - start_seconds,
      label = bounded_string(request.params.label or "custom", 160),
    }
  end
  if kind == "time_selection" then
    local ok, start_seconds, end_seconds = call_reaper("GetSet_LoopTimeRange", false, false, 0, 0, false)
    if not ok or type(start_seconds) ~= "number" or type(end_seconds) ~= "number" or end_seconds <= start_seconds then
      return nil, d21_render_error("TIME_SELECTION_EMPTY", "Render bounds requested time selection, but no active time selection was found.", {})
    end
    return {
      resolved_kind = "time_selection",
      start_position_seconds = start_seconds,
      end_position_seconds = end_seconds,
      duration_seconds = end_seconds - start_seconds,
      label = "time_selection",
    }
  end
  if kind == "region" then
    local region, code, message = d21_render_resolve_region(request)
    if not region then
      return nil, d21_render_error(code, message, {})
    end
    return {
      resolved_kind = "region",
      region_ref = d21_render_region_ref(region.index),
      start_position_seconds = region.start_seconds,
      end_position_seconds = region.end_seconds,
      duration_seconds = region.end_seconds - region.start_seconds,
      label = region.name,
    }
  end
  if kind == "selected_project_regions" then
    return nil, d21_render_error("SELECTED_REGIONS_UNAVAILABLE", "Selected project regions are not exposed by the bounded D21 read route.", {})
  end
  local ok_length, project_length = call_reaper("GetProjectLength", project)
  local end_seconds = ok_length and first_number(project_length) or 0
  return {
    resolved_kind = "entire_project",
    start_position_seconds = 0,
    end_position_seconds = end_seconds,
    duration_seconds = end_seconds,
    label = "entire_project",
  }
end

local function read_render_settings(request)
  local project = d21_render_current_project()
  local start_seconds = d21_render_number(project, "RENDER_STARTPOS", 0)
  local end_seconds = d21_render_number(project, "RENDER_ENDPOS", 0)
  return d21_render_summary(request, {
    bounds_flag = math.floor(d21_render_number(project, "RENDER_BOUNDSFLAG", 0)),
    start_position_seconds = start_seconds,
    end_position_seconds = end_seconds,
    sample_rate = math.floor(d21_render_number(project, "RENDER_SRATE", 0)),
    channel_count = math.floor(d21_render_number(project, "RENDER_CHANNELS", 0)),
    ["output_directory"] = d21_render_string(project, "RENDER_FILE", 240),
    filename_pattern = d21_render_string(project, "RENDER_PATTERN", 160),
    format_fingerprint = bounded_string(d21_render_string(project, "RENDER_FORMAT", 80), 80),
    render_flags = json_array({}),
  }), nil, json_array({}), json_array({}), json_array({})
end

local function resolve_render_bounds(request)
  local bounds, err = d21_render_bounds_from_kind(request)
  if err then
    return nil, err
  end
  return d21_render_summary(request, bounds), nil, json_array({}), json_array({}), json_array({})
end

local function d21_render_target_name(pattern, label, index)
  local value = pattern
  if type(value) ~= "string" or value == "" then
    value = "$project"
  end
  value = value:gsub("%$region", label ~= "" and label or ("region_" .. tostring(index)))
  value = value:gsub("%$project", "current_project")
  value = value:gsub("[/\\:%c]", "_")
  if value == "" then
    value = "render_target_" .. tostring(index)
  end
  return bounded_string(value, 160)
end

local function preview_render_targets(request)
  local limit = bounded_limit(request, request.params.max_targets, 8, 32)
  local project = d21_render_current_project()
  local output_dir = bounded_string(request.params.output_directory or d21_render_string(project, "RENDER_FILE", 240), 240)
  local filename_pattern = bounded_string(request.params.filename_pattern or d21_render_string(project, "RENDER_PATTERN", 160), 160)
  local bounds_kind = request.params.bounds_kind or "current_settings"
  local targets = json_array({})
  local refs = json_array({})
  if bounds_kind == "selected_project_regions" then
    local regions = d21_render_regions(project, limit)
    for index = 1, #regions do
      local region = regions[index]
      local name = d21_render_target_name(filename_pattern, region.name, index)
      local ref = "file:render-preview:" .. tostring(index)
      targets[#targets + 1] = {
        file_ref = ref,
        ["output_directory"] = output_dir,
        filename = name,
        region_ref = d21_render_region_ref(region.index),
      }
      refs[#refs + 1] = d21_render_ref_object("file", ref, "render_preview", tostring(index), "Predicted render target.")
    end
  else
    local bounds, err = d21_render_bounds_from_kind({
      params = {
        bounds_kind = bounds_kind == "current_settings" and "entire_project" or bounds_kind,
        start_position_seconds = request.params.start_position_seconds,
        end_position_seconds = request.params.end_position_seconds,
        label = request.params.label,
      },
      refs = request.refs,
    })
    if err then
      return nil, err
    end
    local ref = "file:render-preview:1"
    targets[#targets + 1] = {
      file_ref = ref,
      ["output_directory"] = output_dir,
      filename = d21_render_target_name(filename_pattern, bounds.label, 1),
      bounds = bounds,
    }
    refs[#refs + 1] = d21_render_ref_object("file", ref, "render_preview", "1", "Predicted render target.")
  end
  return d21_render_summary(request, {
    targets = targets,
    target_count = #targets,
    truncated = #targets >= limit,
  }), nil, refs, json_array({}), refs
end

local function read_region_render_matrix(request)
  local region, code, message = d21_render_resolve_region(request)
  if not region then
    return nil, d21_render_error(code, message, {})
  end
  local project = d21_render_current_project()
  local limit = bounded_limit(request, request.params.limit, 64, 128)
  local tracks = json_array({})
  local refs = json_array({})
  for matrix_index = 0, limit - 1 do
    local ok, track = call_reaper("EnumRegionRenderMatrix", project, region.index, matrix_index)
    if not ok or not track then
      break
    end
    local ref = d21_render_track_ref(track)
    tracks[#tracks + 1] = {
      track_ref = ref,
      index = d21_render_track_index(track),
    }
    refs[#refs + 1] = d21_render_ref_object("track", ref, "guid_or_index", ref, "Track in region render matrix.")
  end
  return d21_render_summary(request, {
    region_ref = d21_render_region_ref(region.index),
    tracks = tracks,
    track_count = #tracks,
    truncated = #tracks >= limit,
  }), nil, refs, json_array({}), refs
end
return {
  exports = { read_render_settings = read_render_settings, resolve_render_bounds = resolve_render_bounds, preview_render_targets = preview_render_targets, read_region_render_matrix = read_region_render_matrix },
  shared = {  },
}
end)

-- OpenReaper bridge handler module: reaper/bridge/src/handlers/tracks/d9_tracks_mixer_route.lua
__openreaper_register_handler_module("tracks/d9_tracks_mixer_route.lua", function()
-- Extracted D9 tracks mixer/basic control handlers.

local function d9_tracks_error(code, message, details, recoverable)
  return nil, {
    code = code,
    message = message,
    recoverable = recoverable ~= false,
    details = details or {},
  }
end

local function d9_tracks_refs(...)
  local refs = json_array({})
  for index = 1, select("#", ...) do
    local ref = select(index, ...)
    if ref then
      refs[#refs + 1] = ref
    end
  end
  return refs
end

local function d9_tracks_append_refs(target, source)
  if not is_json_array(source) then
    return target
  end
  for index = 1, #source do
    target[#target + 1] = source[index]
  end
  return target
end

local function d9_tracks_limit(request, default_limit, hard_limit)
  local value = tonumber(request.params and request.params.limit)
  if not value or value < 1 then
    value = default_limit
  end
  value = math.floor(value)
  if value > hard_limit then
    value = hard_limit
  end
  return value
end

local function d9_tracks_summary(request, readback)
  readback = readback or {}
  readback.capability = request.pack.capability
  readback.pack = request.pack.id
  readback.risk = request.pack.risk
  readback.readback_status = "passed"
  readback.undo_evidence = request.pack.risk == "write" and "required" or "none"
  readback.artifacts_allowed = false
  readback.truncated = readback.truncated == true
  return readback
end

local function d9_tracks_guid(track)
  local ok, guid = call_reaper("GetTrackGUID", track)
  return ok and first_string(guid) or nil
end

local function d9_tracks_index(track)
  local ok_number, number = call_reaper("GetMediaTrackInfo_Value", track, "IP_TRACKNUMBER")
  if ok_number and type(number) == "number" and number > 0 then
    return math.floor(number - 1)
  end
  local ok_count, count = call_reaper("CountTracks", 0)
  local total = ok_count and first_number(count) or 0
  for index = 0, total - 1 do
    local ok_track, candidate = call_reaper("GetTrack", 0, index)
    if ok_track and candidate == track then
      return index
    end
  end
  return 0
end

local function d9_tracks_ref_string(track)
  local guid = d9_tracks_guid(track)
  if guid then
    return "track:guid:" .. guid
  end
  return "track:index:" .. tostring(d9_tracks_index(track))
end

local function d9_tracks_name(track)
  local ok, _, name = call_reaper("GetTrackName", track, "")
  return bounded_string(ok and first_string(name) or "", 160)
end

local function d9_tracks_object_ref(track)
  local ref = d9_tracks_ref_string(track)
  local scheme, value = ref:match("^track:([^:]+):(.+)$")
  return {
    kind = "track",
    ref = ref,
    identity = {
      scheme = scheme or "index",
      value = tostring(value or d9_tracks_index(track)),
    },
    display = {
      name = d9_tracks_name(track),
      index = d9_tracks_index(track),
    },
  }
end

local function d9_tracks_find_by_guid(guid)
  local ok_count, count = call_reaper("CountTracks", 0)
  local total = ok_count and first_number(count) or 0
  for index = 0, total - 1 do
    local ok_track, track = call_reaper("GetTrack", 0, index)
    if ok_track and track and d9_tracks_guid(track) == guid then
      return track
    end
  end
  return nil
end

local function d9_tracks_resolve_token(token)
  if not is_string(token) then
    return nil
  end
  local selected_index = token:match("^selected:(%d+)$") or token:match("^track:selected:(%d+)$")
  if selected_index then
    local ok, track = call_reaper("GetSelectedTrack", 0, tonumber(selected_index))
    return ok and track or nil
  end
  local index = token:match("^index:(%d+)$") or token:match("^track:index:(%d+)$")
  if index then
    local ok, track = call_reaper("GetTrack", 0, tonumber(index))
    return ok and track or nil
  end
  local guid = token:match("^guid:(.+)$") or token:match("^track:guid:(.+)$")
  if guid then
    return d9_tracks_find_by_guid(guid)
  end
  return nil
end

local function d9_tracks_from_ref_object(ref)
  if not is_object(ref) or ref.kind ~= "track" then
    return nil
  end
  local identity = is_object(ref.identity) and ref.identity or {}
  if identity.scheme == "selected" then
    return d9_tracks_resolve_token("selected:" .. tostring(identity.value))
  elseif identity.scheme == "index" then
    return d9_tracks_resolve_token("index:" .. tostring(identity.value))
  elseif identity.scheme == "guid" then
    return d9_tracks_resolve_token("guid:" .. tostring(identity.value))
  end
  return d9_tracks_resolve_token(ref.ref)
end

local function d9_tracks_from_request_refs(request)
  local tracks = {}
  if is_json_array(request.refs) then
    for index = 1, #request.refs do
      local track = d9_tracks_from_ref_object(request.refs[index])
      if track then
        tracks[#tracks + 1] = track
      end
    end
  end
  return tracks
end

local function d9_tracks_primary_from_request_refs(request)
  local tracks = d9_tracks_from_request_refs(request)
  if tracks[1] then
    return tracks[1]
  end
  return nil
end

local function d9_tracks_solo_label(value)
  if value == 1 then
    return "solo"
  elseif value == 2 then
    return "solo_in_place"
  end
  return "off"
end

local function d9_tracks_numeric(track, key, fallback)
  local ok, value = call_reaper("GetMediaTrackInfo_Value", track, key)
  return ok and first_number(value) or fallback
end

local function d9_tracks_mixer_summary(track)
  return {
    track_ref = d9_tracks_ref_string(track),
    index = d9_tracks_index(track),
    name = d9_tracks_name(track),
    selected = d9_tracks_numeric(track, "I_SELECTED", 0) == 1,
    muted = d9_tracks_numeric(track, "B_MUTE", 0) == 1,
    solo_mode = d9_tracks_solo_label(d9_tracks_numeric(track, "I_SOLO", 0)),
    record_armed = d9_tracks_numeric(track, "I_RECARM", 0) == 1,
    volume = d9_tracks_numeric(track, "D_VOL", 1),
    pan = d9_tracks_numeric(track, "D_PAN", 0),
    width = d9_tracks_numeric(track, "D_WIDTH", 1),
    folder_depth = math.floor(d9_tracks_numeric(track, "I_FOLDERDEPTH", 0) or 0),
  }
end

local function d9_tracks_all(limit)
  local ok_count, count = call_reaper("CountTracks", 0)
  local total = ok_count and math.max(0, math.floor(first_number(count) or 0)) or 0
  local tracks = {}
  local max_index = math.min(total, limit)
  for index = 0, max_index - 1 do
    local ok_track, track = call_reaper("GetTrack", 0, index)
    if ok_track and track then
      tracks[#tracks + 1] = track
    end
  end
  return tracks, total, total > limit
end

local function d9_tracks_selected(limit)
  local ok_count, count = call_reaper("CountSelectedTracks", 0)
  local total = ok_count and math.max(0, math.floor(first_number(count) or 0)) or 0
  local tracks = {}
  local max_index = math.min(total, limit)
  for index = 0, max_index - 1 do
    local ok_track, track = call_reaper("GetSelectedTrack", 0, index)
    if ok_track and track then
      tracks[#tracks + 1] = track
    end
  end
  return tracks, total, total > limit
end

local function list_tracks(request)
  local limit = d9_tracks_limit(request, 64, 256)
  local tracks, total, truncated = d9_tracks_all(limit)
  local rows = json_array({})
  local refs = json_array({})
  local selected_count = 0
  for index = 1, #tracks do
    local summary = d9_tracks_mixer_summary(tracks[index])
    rows[#rows + 1] = {
      track_ref = summary.track_ref,
      index = summary.index,
      name = summary.name,
      selected = summary.selected,
      record_armed = summary.record_armed,
      muted = summary.muted,
      solo_mode = summary.solo_mode,
    }
    if summary.selected then
      selected_count = selected_count + 1
    end
    refs[#refs + 1] = d9_tracks_object_ref(tracks[index])
  end
  return d9_tracks_summary(request, {
    tracks = rows,
    track_count = total,
    selected_count = selected_count,
    truncated = truncated,
  }), nil, json_array({}), json_array({}), refs
