-- Extracted read-only handler: template.midi.resolve_midi_take_ref.

local READ_B_MIDI = {}

function READ_B_MIDI.handler_error(code, message, details, recoverable)
  return nil, {
    code = code,
    message = message,
    recoverable = recoverable ~= false,
    details = details or {},
  }
