    return READ_B_MIDI.handler_error("PARAMS_INVALID", "MIDI note cursor must be a non-negative decimal string.", {
      reason_code = "CURSOR_INVALID",
      cursor = bounded_string(request.params.cursor, 80),
    })
  end
